impl std::fmt::Display for Item {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.resource_location())
    }
}

impl AsRef<str> for Item {
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}
